/* @lc app=leetcode id=3795 lang=kotlin */ class Solution { fun minLength(nums: IntArray, k: Int): Int = IntArray(100001).let { cnt -> LongArray(1).let { ds -> nums.indices.fold(0 to Int.MAX_VALUE) { (l, best), r -> cnt.set(nums[r], cnt[nums[r]] + 1).let { if (cnt[nums[r]] == 1) ds[0] += nums[r].toLong() }.let { generateSequence(l to best) { (ll, b) -> if (ds[0] >= k) (cnt.set(nums[ll], cnt[nums[ll]] - 1).let { if (cnt[nums[ll]] == 0) ds[0] -= nums[ll].toLong() }.let { ll + 1 to minOf(b, r - ll + 1) }) else null }.last() } }.second.let { if (it == Int.MAX_VALUE) -1 else it } } } }